package com.kioskmdm;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 protected void onCreate(Bundle b){super.onCreate(b);if(!Prefs.setup(this)){setup();return;}launch();}
 protected void onResume(){super.onResume();if(Prefs.setup(this)&&!Prefs.maintenance(this))new Handler().postDelayed(this::launch,250);}
 void setup(){LinearLayout l=UI.root(this,"הגדרת Kiosk MDM");TextView st=new TextView(this);st.setText(Policy.owner(this)?"Device Owner פעיל":"נדרש Device Owner לפני נעילה סופית");l.addView(st);EditText pin=new EditText(this);pin.setHint("קוד מנהל - לפחות 4 ספרות");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);l.addView(pin);Spinner sp=new Spinner(this);List<String> pk=new ArrayList<>(),names=new ArrayList<>();PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);for(ResolveInfo r:pm.queryIntentActivities(q,0)){String p=r.activityInfo.packageName;if(p.equals(getPackageName()))continue;pk.add(p);names.add(r.loadLabel(pm)+" — "+p);}sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));l.addView(sp);Button overlay=UI.b(this,"אשר כפתור הגדרות צף");overlay.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=23&&!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+getPackageName())));});l.addView(overlay);Button write=UI.b(this,"אשר שליטה בבהירות");write.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=23&&!Settings.System.canWrite(this))startActivity(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,android.net.Uri.parse("package:"+getPackageName())));});l.addView(write);Button go=UI.b(this,"סיום הגדרה ונעילת המכשיר");go.setOnClickListener(v->{if(!Policy.owner(this)){UI.msg(this,"האפליקציה עדיין אינה Device Owner");return;}if(pin.getText().length()<4||pk.isEmpty()){UI.msg(this,"בחר אפליקציה וקוד של לפחות 4 ספרות");return;}String p=pk.get(sp.getSelectedItemPosition());Prefs.finish(this,p,pin.getText().toString());Policy.apply(this,p);startService(new Intent(this,QuickAccessService.class));launch();});l.addView(go);setContentView(l);}
 void launch(){if(Prefs.maintenance(this))return;String p=Prefs.main(this);if(p.isEmpty())return;Policy.applyBlocked(this);startService(new Intent(this,QuickAccessService.class));if(Policy.owner(this))try{startLockTask();}catch(Exception ignored){}Intent i=getPackageManager().getLaunchIntentForPackage(p);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED);startActivity(i);}else UI.msg(this,"האפליקציה הראשית אינה זמינה");}
}